create or replace function public.crm_execute_ai_action(p_action_id uuid,p_body text) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); a public.crm_ai_actions%rowtype; m public.crm_messages%rowtype; body text:=btrim(coalesce(p_body,'')); begin if uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if; if body='' then raise exception 'MESSAGE_EMPTY' using errcode='22023'; end if; if length(body)>10000 then raise exception 'MESSAGE_TOO_LONG' using errcode='22001'; end if; select * into a from public.crm_ai_actions where id=p_action_id and user_id=uid and status='accepted' for update; if not found then raise exception 'AI_ACTION_NOT_EXECUTABLE' using errcode='P0001'; end if; if a.action_type not in ('payment_follow_up','sales_follow_up','recovery_follow_up','qualification','upsell_or_post_sale') then raise exception 'ACTION_NOT_EXECUTABLE' using errcode='P0001'; end if; update public.crm_ai_actions set status='executing' where id=a.id; perform pg_advisory_xact_lock(hashtextextended(a.conversation_id::text,0)); if not exists(select 1 from public.crm_conversations where id=a.conversation_id and user_id=uid) then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002'; end if; select * into m from public.crm_messages where user_id=uid and client_message_id=('ai:'||a.id) limit 1; if not found then insert into public.crm_messages(conversation_id,user_id,direction,channel,body,metadata,sender_id,client_message_id) values(a.conversation_id,uid,'outbound','webchat',body,jsonb_build_object('source','crm_ai_agent','action_id',a.id,'action_type',a.action_type),uid,'ai:'||a.id) returning * into m; end if; update public.crm_ai_actions set status='executed',executed_at=now() where id=a.id; return jsonb_build_object('ok',true,'action_id',a.id,'status','executed','executed_at',now(),'message',to_jsonb(m)); end; $$;
revoke all on function public.crm_execute_ai_action(uuid,text) from public,anon;
grant execute on function public.crm_execute_ai_action(uuid,text) to authenticated;
